ALTER TABLE sys_user ADD email_address VARCHAR(254);
ALTER TABLE sys_user ADD totp_secret VARCHAR(1024);
ALTER TABLE sys_user ADD totp_pending VARCHAR(1024);
ALTER TABLE sys_user ADD totp_pending_until BIGINT;
ALTER TABLE sys_user ADD totp_step BIGINT NOT NULL DEFAULT -1;
CREATE UNIQUE INDEX uq_user_email ON sys_user(email_address);
CREATE TABLE account_token(token_hash VARCHAR(64) PRIMARY KEY,user_id VARCHAR(36) NOT NULL REFERENCES sys_user(id),purpose VARCHAR(20) NOT NULL,email_address VARCHAR(254),expires_at BIGINT NOT NULL);
CREATE TABLE mfa_recovery(user_id VARCHAR(36) NOT NULL REFERENCES sys_user(id),token_hash VARCHAR(64) NOT NULL,PRIMARY KEY(user_id,token_hash));
CREATE TABLE dav_credential(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL REFERENCES sys_user(id),label VARCHAR(80) NOT NULL,token_hash VARCHAR(64) NOT NULL UNIQUE,read_only BOOLEAN NOT NULL,expires_at BIGINT NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE system_setting(name VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL);
CREATE TABLE storage_policy(id VARCHAR(12) PRIMARY KEY,name VARCHAR(80) NOT NULL,endpoint VARCHAR(500) NOT NULL,bucket VARCHAR(100) NOT NULL,access_key VARCHAR(1024) NOT NULL,secret_key VARCHAR(2048) NOT NULL,region VARCHAR(80),enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE maintenance_job(id VARCHAR(36) PRIMARY KEY,kind VARCHAR(32) NOT NULL,status VARCHAR(24) NOT NULL,source_backend VARCHAR(16),target_backend VARCHAR(16),completed BIGINT NOT NULL DEFAULT 0,total BIGINT NOT NULL DEFAULT 0,error VARCHAR(300),created_at BIGINT NOT NULL,updated_at BIGINT NOT NULL);
CREATE TABLE entry_tag(entry_id VARCHAR(36) NOT NULL REFERENCES drive_entry(id) ON DELETE CASCADE,tag VARCHAR(40) NOT NULL,PRIMARY KEY(entry_id,tag));
CREATE TABLE entry_index(entry_id VARCHAR(36) PRIMARY KEY REFERENCES drive_entry(id) ON DELETE CASCADE,revision BIGINT NOT NULL,body MEDIUMTEXT,status VARCHAR(16) NOT NULL,updated_at BIGINT NOT NULL);
ALTER TABLE file_share ADD share_mode VARCHAR(16) NOT NULL DEFAULT 'READ';
ALTER TABLE file_share ADD title VARCHAR(180);
ALTER TABLE file_share ADD views BIGINT NOT NULL DEFAULT 0;
ALTER TABLE file_share ADD downloads BIGINT NOT NULL DEFAULT 0;
ALTER TABLE file_share ADD collected BIGINT NOT NULL DEFAULT 0;
CREATE TABLE share_member(share_id VARCHAR(36) NOT NULL REFERENCES file_share(id) ON DELETE CASCADE,entry_id VARCHAR(36) NOT NULL REFERENCES drive_entry(id) ON DELETE CASCADE,PRIMARY KEY(share_id,entry_id));
CREATE TABLE share_event(id VARCHAR(36) PRIMARY KEY,share_id VARCHAR(36) NOT NULL REFERENCES file_share(id) ON DELETE CASCADE,action VARCHAR(16) NOT NULL,created_at BIGINT NOT NULL);
CREATE INDEX ix_share_event ON share_event(share_id,created_at);
-- MySQL does not enforce inline REFERENCES clauses; declare actual constraints explicitly.
ALTER TABLE account_token ADD CONSTRAINT fk_account_token_user FOREIGN KEY(user_id) REFERENCES sys_user(id);
ALTER TABLE mfa_recovery ADD CONSTRAINT fk_mfa_user FOREIGN KEY(user_id) REFERENCES sys_user(id);
ALTER TABLE dav_credential ADD CONSTRAINT fk_dav_user FOREIGN KEY(user_id) REFERENCES sys_user(id);
ALTER TABLE entry_tag ADD CONSTRAINT fk_tag_entry FOREIGN KEY(entry_id) REFERENCES drive_entry(id) ON DELETE CASCADE;
ALTER TABLE entry_index ADD CONSTRAINT fk_index_entry FOREIGN KEY(entry_id) REFERENCES drive_entry(id) ON DELETE CASCADE;
ALTER TABLE share_member ADD CONSTRAINT fk_member_share FOREIGN KEY(share_id) REFERENCES file_share(id) ON DELETE CASCADE;
ALTER TABLE share_member ADD CONSTRAINT fk_member_entry FOREIGN KEY(entry_id) REFERENCES drive_entry(id) ON DELETE CASCADE;
ALTER TABLE share_event ADD CONSTRAINT fk_event_share FOREIGN KEY(share_id) REFERENCES file_share(id) ON DELETE CASCADE;
